UPDATE businesses SET description = 'African Bank Eerste River is the African Bank branch at 8 Plein Street, inside the Grand Central Shopping Centre in Eerste River. It serves residents of Eerste River and the surrounding eastern suburbs who prefer to handle their banking in person, close to home.

The branch offers African Bank’s range of retail banking products, including day-to-day transactional accounts, savings accounts, personal loans and investment options. Consultants help customers open accounts, apply for credit and choose the products that suit their needs, and service at the branch is quick and efficient. The bank describes itself as a bank “for the people, by the people”, with its focus on everyday South Africans. The branch has wheelchair access, and its spot in the shopping centre makes it easy to combine a bank visit with other errands. African Bank is at Grand Central Shopping Centre, 8 Plein Street, Eerste River.', description_enriched_at = datetime('now') WHERE slug = 'african-bank-eerste-river-eerste-river' AND description = 'African Bank Eerste River is a bank branch on Plein Street, Eerste River.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
